import { test, expect } from '@playwright/test';

test.describe('Skip-to-content link accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should have a skip-to-content link visible on page load', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to content/i });
    await expect(skipLink).toBeVisible();
  });

  test('should have skip-to-content link with correct href attribute', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to content/i });
    const href = await skipLink.getAttribute('href');
    expect(href).toBeTruthy();
    expect(href).toMatch(/^#/);
  });

  test('should focus skip-to-content link when tabbing from start', async ({ page }) => {
    await page.keyboard.press('Tab');
    const skipLink = page.getByRole('link', { name: /skip to content/i });
    await expect(skipLink).toBeFocused();
  });

  test('should navigate to main content when skip link is clicked', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to content/i });
    const href = await skipLink.getAttribute('href');

    await skipLink.click();

    const mainContent = page.locator(href || '#main-content');
    await expect(mainContent).toBeFocused();
  });

  test('should have skip-to-content link before navigation elements', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to content/i });
    const nav = page.getByRole('navigation').first();

    const skipLinkBox = await skipLink.boundingBox();
    const navBox = await nav.boundingBox();

    expect(skipLinkBox).toBeTruthy();
    expect(navBox).toBeTruthy();

    if (skipLinkBox && navBox) {
      expect(skipLinkBox.y).toBeLessThanOrEqual(navBox.y);
    }
  });
});
